class gsl_vector(ctypes.POINTER(gsl_complex))

gsl_vector_ptr = ctypes.POINTER(gsl_complex)
gsl_matrix_complex = ctypes.POINTER((ctypes.c_void_p * (ctypes.c_size_t * 2)))

def load_gsl_matrix_complex(matrix, size):
    matrix_complex = gsl_matrix_complex()
    for i in range(size):
        row = (ctypes.c_void_p * 2)()
        for j in range(size):
            real = np.real(matrix[i][j])
            imag = np.imag(matrix[i][j])
            complex_num = gsl_complex(real, imag)
            row[j] = ctypes.pointer(complex_num)
        matrix_complex[i] = row
    return matrix_complex

def compute_eigen(matrix_complex, size):
    eigen_workspace = 0
    eigen_vectors = (gsl_vector * size)()
    eigen_values = (ctypes.c_double * size)()

    gsl.gsl_eigen_hermv_alloc(ctypes.byref(eigen_workspace), size)
    try:
        gsl.gsl_eigen_hermv(matrix_complex, ctypes.byref(eigen_workspace), size, eigen_vectors, eigen_values)
    except Exception as e:
        raise Exception("GSL error: " + str(e))
