def symmetric_rank2_update(order, uplo, N, alpha, X, incX, Y, incY, A, lda):
    if order not in [0, 1]:
        raise ValueError('Invalid order specified')
    if uplo not in [0, 1]:
        raise ValueError('Invalid uplo specified')
    if isinstance(N, int) and N > 0:
        n = c_int(int(N))
    else:
        raise ValueError('Invalid N specified')
    if isinstance(alpha, (int, float)):
        alpha_c = c_float(float(alpha))
    else:
        raise ValueError('Invalid alpha specified')
    X_c = np.array(X).flatten().astype(c_float)
    incX_c = c_int(int(incX))
    Y_c = np.array(Y).flatten().astype(c_float)
    incY_c = c_int(int(incY))
    A_c = np.array(A).flatten().astype(c_float)
    lda_c = c_int(int(lda))
    try:
        gslcblas.cblas_ssyr2(order, uplo, n, alpha_c, X_c, incX_c, Y_c, incY_c, A_c, lda_c)
    except Exception as e:
        raise
    return A_c.tolist()

