import random
from scipy import stats

def compute_statistics(N, K, sigma, N_sigma):
    if N <= 0:
        raise ValueError("N should be greater than zero")

    ctypes.CDLL(\"/usr/local/gsl/lib/libgslcblas.so\", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL(\"/usr/local/gsl/lib/libgsl.so\")

    rng = gsl.GSL_RNG_random_init()
    rvector = gsl.GSL_vector_double()
    workspace = gsl.GSL_vector_workspace()

    for i in range(N):
        if i < N_sigma[0]:
            noise = random.gauss(0, sigma[0])
        else:
            next_index = np.where(np.array(N_sigma) > i)[0][0] - 1
            noise = random.gauss(0, sigma[next_index])

        gsl.GSL_vector_set(rvector, i, i + noise)

    data = ctypes.c_double * N
    array = data()
    for i in range(N):
        array[i] = rvector.data[i]

    stats_data = ctypes.POINTER(ctypes.c_double) * K
    window_stats = stats_data()
    for i in range(K-1):
        window_stats[i] = 0

    window_stats[K-1] = array[N-1]
    for i in range(N - K + 1):
        j = i + K - 1
        if i == N - K:
            window_stats[0] = array[j]
        else:
            for k in range(K):
                if k == K-1:
                    window_stats[k] += array[j-k+K]
                else:
                    window_stats[k] += array[j-k]

    median = 0
    for i in range(N):
        if i < K-1:
            median += array[i]
        else:
            median += window_stats[0]

    median /= N

    sd = 0
    for i in range(N):
        sd += (array[i] - median)**2
    sd = np.sqrt(sd / N)

    mad = stats.median_abs_deviation(array)
    iqr = stats.iqr(array)
    sn = stats.sem(array, axis=0)
    qn = np.percentile(array, 75)

    result = []
    for i in range(N):
        if i < K-1:
            result.append({'original': array[i], 'MAD': mad, 'IQR': iqr, 'Sn': sn, 'Qn': qn, 'SD': sd})
        else:
            result.append({'original': window_stats[0], 'MAD': mad, 'IQR': iqr, 'Sn': sn, 'Qn': qn, 'SD': sd})

    return json.dumps(result)

def assert_test(N):
    N_sigma = [2]
    K = 3
    sigma = [1.5]

    result = compute_statistics(N, K, sigma, N_sigma)
    expected_result = [[{'original': i+0, 'MAD': 0.75, 'IQR': 1.25, 'Sn': 0.7071067811865476, 'Qn': 1.5, 'SD': 1.485246125}] for i in range(N)]
    assert result == json.dumps(expected_result)

