_gsl_linalg_LU_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int)]
_gsl_linalg_LU_decomp.restype = None

class GSLMatrix:
    def __init__(self, data: List[List[float]]):
        self.data = np.array(data)

    def get_ptr(self) -> ctypes.POINTER(ctypes.c_double):
        return self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

class GSLPermutation:
    def __init__(self, data: List[int]):
        self.data = np.array(data)

    def get_ptr(self) -> ctypes.POINTER(ctypes.c_int):
        return self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_int))

def lu_decomposition(matrix: List[List[float]]) -> Tuple[List[List[float]], List[int], int]:
    n = len(matrix)
    ptr_matrix = GSLMatrix(matrix).get_ptr()
    ptr_perm = np.zeros(n, dtype=np.int32)
    signum = 0

    _gsl_linalg_LU_decomp(ptr_matrix, n, ptr_perm.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    lu_matrix = [[0.0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            lu_matrix[i][j] = ptr_matrix[i * n + j]

    return [map(list, np.array(lu_matrix).tolist()), ptr_perm.tolist(), signum]

