class gsl_vector(Structure):
    _fields_ = [('data', ctypes.c_double * 1)]

class gsl_bspline_workspace(Structure):
    _fields_ = [('workspace', ctypes.POINTER(c_void_p)])

def bspline_wlssolve(x, y, weights=None):
    if len(x) != len(y):
        raise ValueError('x and y must have the same length')
    if weights is not None and len(weights) != len(x):
        raise ValueError('weights must have the same length as x')

    x_ptr = (ctypes.c_double * len(x))(*x)
    y_ptr = (ctypes.c_double * len(y))(*y)
    if weights is not None:
        w_ptr = (ctypes.c_double * len(weights))(*weights)
    else:
        w_ptr = None

    v_ptr = gsl_vector()
    v_ptr.data[:] = 0.
    work_ptr = gsl_bspline_workspace()
    result_ptr = gsl.bspline_wlssolve(x_ptr, y_ptr, w_ptr, len(x)-1, v_ptr, work_ptr)
    if result_ptr is None:
        raise RuntimeError('gsl bspline_wlssolve failed')

    coefficients = [result_ptr[i] for i in range(len(v_ptr))]
    chi_squared = (sum((y - np.polyval(coefficients[::-1], x)) ** 2 for coeff, x in zip(coefficients, x))) / len(x) if weights is None else (sum(((y - np.polyval(coefficients[::-1], x)) * w)**2 for coeff, x, w in zip(coefficients, x, weights))) / sum(1/w if w != 0 else 0.5 for w in weights)

    return json.dumps({'coefficients': [str(c) for c in coefficients], 'chi_squared': str(chi_squared)}),

