class GSLFunction:
    def __init__(self, func):
        self.func = func

    def compute_derivative(self, x):
        gsl_function = POINTER(c_double)()
        for i in range(1, 5):
            gsl_function[i] = self.func(x + (i-2)*0.01)

        result = c_float()
        error = c_double()

        gsl.diff_backward(gsl_function, len(gsl_function), x, byref(result), byref(error))

        return {"derivative": float(result.value), "error": float(error.value)}

    def linear_func(self, x):
        return 2*x

    def quadratic_func(self, x):
        return x**2

