    def __init__(self):
        self.gsl_rstat_quantile_workspace = None

    def allocate(self):
        self.gsl_rstat_quantile_workspace = ctypes.c_void_p()
        self.gsl_rstat_quantile_workspace = ctypes.c_void_p(gsl.gsl_rstat_quantile_alloc())

    def reset(self):
        if not isinstance(self.gsl_rstat_quantile_workspace, (ctypes.c_void_p)):
            raise ValueError("Workspace must be allocated before resetting")
        gsl.gsl_rstat_quantile_reset(self.gsl_rstat_quantile_workspace)

    def add(self, p, values):
        if not isinstance(self.gsl_rstat_quantile_workspace, (ctypes.c_void_p)):
            raise ValueError("Workspace must be allocated and reset before adding values")
        values_ptr = (c_double * len(values))(*values)
        ptr = ctypes.pointer(values_ptr)
        gsl.gsl_rstat_quantile_add(self.gsl_rstat_quantile_workspace, p, ptr)

    def get(self, p):
        if not isinstance(self.gsl_rstat_quantile_workspace, (ctypes.c_void_p)):
            raise ValueError("Workspace must be allocated and reset before getting values")
        result = c_double()
        gsl.gsl_rstat_quantile_get(self.gsl_rstat_quantile_workspace, p, ctypes.byref(result))
        return result.value

    def free(self):
        if not isinstance(self.gsl_rstat_quantile_workspace, (ctypes.c_void_p)):
            raise ValueError("Workspace must be allocated before freeing")
        gsl.gsl_rstat_quantile_free(self.gsl_rstat_quantile_workspace)

