                                       isinstance(obj.gsl_rstat_quantile_workspace,
                                                  (ctypes.c_void_p))),
                        "values": [] if not obj.gsl_rstat_quantile_workspace else 
                                   [float(x) for x in np.array(obj.get(p).flatten())],
                        "free": bool(obj.gsl_rstat_quantile_workspace and
                                     isinstance(obj.gsl_rstat_quantile_workspace,
                                                (ctypes.c_void_p)) and 
                                     c_double(*obj.free()).value == 0)
