class Multiset:
    def __init__(self, n):
        self.n = n
        self.x = [0] * (n + 1)

    def multiset_operation(self):
        for i in range(1, self.n + 1):
            for j in range(i, self.n + 1):
                self.x[j] += 1

def python_multiset(n):
    ms = Multiset(n)
    ms.multiset_operation()
    return json.dumps({"Candidate_solution": str(ms.x)})

